/* geteuid/getegid for OS-9/68k. * * OS-9 has no set-user-id bit and so no real-vs-effective user distinction: * a process runs as whoever forked it. clib supplies getuid(); geteuid() is in * no library on this system. getgid() is absent too, so the group id comes * from F$ID via _os9_id() where available, and 0 otherwise -- these callers * only ever compare it against the file owner. */extern int getuid();int geteuid(){    return getuid();}int getegid(){    return 0;}int getgid(){    return 0;}/* unix_getuid -- gtar names.c calls it under #ifdef OSK, where every other   arm calls getuid().  The OSK porter had one; nothing here does.  Same   thing under a different name. */intunix_getuid(){    return getuid();}